,$q$partners$q$,$q$NBIS$q$,$q$Grubhub$q$,$q${4}$q$::int[],$q${notes}$q$::text[],null,null,null,$q$Via Avride, a Nebius business unit (parent rule, 2026-10-21)$q$),(18,$q$partners$q$,$q$NBIS$q$,$q$Hyundai$q$,$q${17}$q$::int[],$q${notes}$q$::text[],null,null,null,$q$Via Avride, a Nebius business unit (parent rule, 2026-10-21)$q$),(19,$q$competes$q$,$q$NBIS$q$,$q$Fireworks AI$q$,$q${28}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(20,$q$competes$q$,$q$NBIS$q$,$q$Together AI$q$,$q${28}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(21,$q$competes$q$,$q$NBIS$q$,$q$Waymo$q$,$q${9}$q$::int[],$q${notes}$q$::text[],null,null,null,$q$Via Avride, a Nebius business unit (parent rule, 2026-10-21)$q$),(22,$q$invests$q$,$q$NVIDIA$q$,$q$NBIS$q$,$q${23,22}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(23,$q$supplies$q$,$q$Toloka$q$,$q$NBIS$q$,$q${12}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(24,$q$sells_to$q$,$q$NBIS$q$,$q$Toloka$q$,$q${12}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Meta$q$ then ticker=$q$META$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Waymo$q$ then ticker=$q$GOOGL$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$NBIS$q$ then ticker=$q$NBIS$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$NBIS FY2025 20-F (M6)$q$,'claude-sonnet-5-5',304545,8701,0.9825,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1513845/000110465926052948/nbis-20251231x20f.htm$q$,r.sec[k],t,true,$q$2026-04-30$q$ from _q where i=r.qs[k]; end loop; end loop;
